            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "Ultimately, literature is nothing but carpentry.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "I would like for my books to have been recognized posthumously, at least in capitalist countries, where they turn you into a kind of merchandise.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "A famous writer who wants to continue writing has to be constantly defending himself against fame.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "In my case, the only advantage to fame is that I have been able to give it a political use.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "The problem is that you're famous for twenty-four hours a day, and you can't say, 'Okay, I won't be famous until tomorrow,' or press a button and say, 'I won't be famous here or now.'", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "I can't think of any one film that improved on a good novel, but I can think of many good films that came from very bad novels.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "Life is not what one lived, but what one remembers and how one remembers it in order to recount it.", Author = "Gabriel García Márquez" },
