            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "But I believe without any doubt at all that our greatest good fortune was that even in the most extreme difficulties we might lose our patience but never our sense of humor.", Author = "Gabriel García Márquez" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gabriel_García_Márquez", Text = "It was impossible to conceive of two creatures so different who got along so well and loved each other so much.", Author = "Gabriel García Márquez" },
